import json,pathlib,copy
from bs4 import BeautifulSoup
r=pathlib.Path('work/research-2026');p=json.load(open(r/'reviewed.json'));xs=json.load(open(r/'verified-sites163-next100-review.json'));before={};dec=[]
assert not (r/'featured165-before.json').exists()
accepted=[56,60,64,66,71,72,75,79,81,86,87,93,95,96,97,99]
fix={56:'Develops and scales U.S. nickel-refining capacity.',64:'Provides a digital practice platform for neurodiverse children and adults to rehearse life skills and prepare for situations such as medical procedures.',66:'Develops robotic systems for aerospace manufacturing and maintenance, including drilling, sanding and inspection.',71:'An algorithmic digital-asset trading and market-making firm.',96:'Develops laser-fusion energy and directed-energy technology.'}
special={56:'Official Westwin Elements body describes nickel refining and a future scale target for 2031. Planned capacity and investment returns are not operating results or independently established outcomes.',60:'Official Whisper Aero About body describes electric propulsion development. Founder biographies are separated from company accomplishments; performance superlatives are not independently established.',64:'Official Wide Therapy body describes digital rehearsal for neurodiverse children and adults. Patent status and claims that skills transfer successfully are not independently verified; the description does not present them as proven outcomes.',66:'Official Wilder Industries body identifies itself as a parent holding company and names Wilder Systems as its aerospace-robotics business. This establishes the parent relationship without assigning all holding-company activities to Wilder Systems.',71:'Official Wintermute privacy notice explicitly identifies Wintermute Trading Limited. Homepage body describes algorithmic trading and liquidity services. The newer U.S. broker-dealer announcement is not treated as registration of this entity.',72:'Official WireScreen body describes corporate-relationship and supply-chain intelligence. Risk flags and claimed comprehensive coverage are not independent findings about listed companies.',75:'Official WISPR Systems body describes commercial drones for mapping, surveying and inspection. Claimed compliance and government-list inclusion are not independently certified.',79:'Official Wonderschool body describes childcare software, provider support and government services. Advertised rankings are not independently verified.',81:'Official Woolpert About body identifies its architecture, engineering, geospatial, planning and technology services.',86:'Official World Gold Council About body identifies a membership organization governed by member representatives and describes research and market development. Member-company ownership is not attributed to the association.',87:'Official Worldpay body and Worldpay LLC footer identify payment services. No current parent ownership is inferred from the branding or related report name.',93:'Official Xactus About body describes mortgage verification and lender services. Speed and quality claims are not independently verified.',95:'Official Xcaliber International body and Pryor address identify tobacco manufacturing and distribution. Product-sale approvals and market-leadership claims are not independently established.',96:'Official Xcimer Company body explicitly describes both laser fusion and directed-energy development. It does not establish operating commercial fusion plants; planned power generation remains development.',97:'Official Xiphos Partners About body describes technology, sustainment and training; footer explicitly names Xiphos Partners, Inc.',99:'Official Xona body and Xona Space Systems, Inc. footer identify satellite positioning, navigation and timing development. Advertised constellation size and performance are not treated as verified deployed coverage.'}
extras={v['index']:v for v in json.load(open(r/'featured165-extra-evidence.json'))}
for n in accepted:
 v=xs[n];i=v['id'];assert p[i]['name']==v['original_name'] and p[i]['review_outcome']!='confirmed';before[i]=copy.deepcopy(p[i]);note=special.get(n,'Official organization body identifies this organization and supports its stated services. Existing ownership evidence is retained; advertised outcomes are not independently verified.')
 p[i].update(description=fix.get(n,v['description']),notes=note,identity_evidence=note,review_outcome='confirmed',checked_at='2026-09-13',as_of='2026-09-13')
 if n==66:p[i]['ownership']='Subsidiary'
 e=v['fetched_evidence'][0];assert e['http_status']==200
 s=BeautifulSoup(open(e['cache_path']).read(),'html.parser')
 for t in s(['script','style','nav','header']):t.decompose()
 ss={s['url']:s for s in p[i]['sources']};ss[e['url']]={'url':e['url'],'label':'Official organization evidence','claim':note};p[i]['sources']=list(ss.values());dec.append(dict(id=i,name=p[i]['name'],decision='confirmed',notes=note,fetched_evidence=v['fetched_evidence'],reviewed_body=' '.join(s.stripped_strings)))
for n,e in extras.items():
 i=xs[n]['id'];p[i]['sources'].append({'url':e['url'],'label':'Official legal or company evidence','claim':special[n]});next(d for d in dec if d['id']==i)['additional_evidence']=e
for name,value in [('before',before),('decisions',dec),('deferred',[])]:
 (r/f'featured165-{name}.json').write_text(json.dumps(value,indent=2)+'\n')
for f in [r/'reviewed.json',pathlib.Path('outputs/2026-research-trial/profiles.json')]:f.write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n')
pathlib.Path('lobbying-map/research/reviewed-2026.json').write_text(json.dumps(p,ensure_ascii=False));print(len(dec),'identity confirmations saved')
